    my $result = eval { Path::Class::Dir::rmtree($dir) };
    if ($@) { like($@, qr/Permission denied/, 'Exception thrown for permission denied'); }
    is($result, undef, 'Returns undef for permission denied');
}

# Test case: Verbose mode
{
    my $dir = Path::Class::Dir->new('existing_dir');
